["Thập tuyên", "EX-UE11", "Ngoài kinh", "Gồm 5 huyệt mỗi bên, lấy tại đỉnh cao nhất của 10 đầu ngón tay.", "Tại chỗ: sưng đau các ngón tay; Toàn thân: sốt cao, viêm Amidan cấp, cấp cứu choáng ngất.", "Châm cứu: chích nặn máu trong viêm Amidan cấp, sốt co giật; châm thẳng vê kim mạnh sâu 0,1 thốn trong cấp cứu choáng ngất.", "Kỳ huyệt (huyệt ngoài đường kinh)"],
["Suyễn tức từ", "Kỳ huyệt", "Ngoài kinh", "Đại Chùy đo ra 1 thốn.", "Hen suyễn, ho, đau cổ gáy, đau lưng trên.", "Châm sâu 0,3-0,5 thốn.", "Kỳ huyệt (huyệt ngoài đường kinh)"],
["Khí suyễn", "Kỳ huyệt", "Ngoài kinh", "Dưới gai đốt sống lưng D7 đo ra 2 thốn (Cứu 10-15’).", "Hen suyễn, ho kéo dài.", "", "Kỳ huyệt (huyệt ngoài đường kinh)"],
["Cảnh căn", "Kỳ huyệt", "Ngoài kinh", "Ở góc giữa cổ và bờ ngoài cơ thang (góc cổ vai).", "Đau cứng cổ gáy, đau vai lưng, vẹo cổ cấp.", "Châm xiên 0,3 - 0,5 thốn; cứu 5 - 10 phút.", "Kỳ huyệt (huyệt ngoài đường kinh)"],
["Yêu nhãn", "Kỳ huyệt", "Ngoài kinh", "Dưới mỏm gai đốt sống L4 đo ngang ra 3 - 4 thốn, chỗ lõm hai bên thắt lưng.", "Đau thắt lưng, tổn thương phần mềm vùng thắt lưng, thận sa, viêm tinh hoàn, bệnh phụ khoa.", "Châm thẳng 0,5 - 1 thốn; cứu 5 - 15 phút.", "Kỳ huyệt (huyệt ngoài đường kinh)"],
["Ngạch trung", "Kỳ huyệt", "Ngoài kinh", "Chỗ lõm chính giữa trán, trên Ấn đường 1 thốn.", "Đau đầu vùng trán, viêm mũi, mất ngủ, hồi hộp, chóng mặt.", "Châm ngang 0,3 - 0,5 thốn.", "Kỳ huyệt (huyệt ngoài đường kinh)"]
